head.script:
scwin.screenId = "jldfil72100";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_isurCd", fn: function () { return String(String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("isurCd")))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name scwin.init_loadList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_action). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_load_list();
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        await scwin.init_loadList();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil72100.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.img_31_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.img_31_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin img_31_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.findIsuDigital('')
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil72100.img_31_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_Search_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_Search_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_Search_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.search()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil72100.btn_Search_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_Search
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_Search = async function () {
    const sbmOptions = {
        id: "tx_fn_Search",
        method: "post",
        action: "/digital/DigitalEtcMarketMgt.do",
        ref: "dma_SearchReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil72100.tx_fn_Search" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_load_list
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_load_list = async function () {
    const sbmOptions = {
        id: "tx_load_list",
        method: "post",
        action: "/digital/DigitalEtcMarketMgt.do",
        ref: "dma_loadListReq",
        target: "dlt_digitalMarketAdmisuList=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil72100.tx_load_list" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @event
 * @name scwin.__on_enter_1_ipt_isuNm
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.__on_enter_1_ipt_isuNm = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin __on_enter_1_ipt_isuNm — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        if(($c.util.getKeyCode(ev))==13){ await scwin.search() }
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil72100.__on_enter_1_ipt_isuNm' }); }
};

/**
 * @method
 * @name scwin.initValue
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.initValue = function () {
    /* sdd-asis-lifecycle:begin fn_InitValue — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    /* empty */
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.search
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.search = async function () {
    /* sdd-asis-lifecycle:begin fn_Search — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if ($c.util.getComponent('cal_startDate').getValue() > $c.util.getComponent('cal_endDate').getValue()) {
        await $c.win.alert('시작일이 종료일보다 이후 일자 입니다.');
        return;
    }
    $c.util.getComponent("ipt_gubunTcYn").setValue(scwin.getCheckBoxValue($('#ipt_gubunTc')));
    $c.util.getComponent("ipt_gubunIcYn").setValue(scwin.getCheckBoxValue($('#ipt_gubunIc')));
    const gubunTcYn = $c.util.getComponent('ipt_gubunTcYn').getValue();
    const gubunIcYn = $c.util.getComponent('ipt_gubunIcYn').getValue();
    let a = 0;
    let b = 0;
    let marketType = 0;
    if (gubunTcYn === "Y") {
        a = 1;
    }
    if (gubunIcYn === "Y") {
        b = 2;
    }
    marketType = a + b;
    $c.util.getComponent('ipt_marketType').setValue(marketType);
    $c.util.getComponent('ipt_method').setValue("searchDigitalMarketManagement");
    $("form[name='digitalListForm']").attr("action", "DigitalEtcMarketMgt.do");
    $("form[name='digitalListForm']").attr("onsubmit", "");
    await scwin.tx_fn_Search();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.getCheckBoxValue
 * @author Inswave
 * @date 2026. 09. 29
 * @param chkObj
 * @returns
 * @hidden N
*/
scwin.getCheckBoxValue = function (chkObj) {
    /* sdd-asis-lifecycle:begin fn_getCheckBoxValue — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (chkObj.is(":checked") === true) {
        return 'Y';
    } else {
        return 'N';
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.findIsuDigital
 * @author Inswave
 * @date 2026. 09. 29
 * @param dgtype
 * @returns
 * @hidden N
*/
scwin.findIsuDigital = async function (dgtype) {
    /* sdd-asis-lifecycle:begin fn_findIsuDigital — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const isurCd = $c.util.getComponent('ipt_isurCd').getValue();
    const corpSearchURL = '/jldfil00171/jldfil00171.xml';
    await $c.win.openPopup((function (__u) { var __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(corpSearchURL), { id: "asstcomWin", scrollbars: false, resizable: false, width: "600", height: "660", type: "pageFramePopup" }, { method: "loadInitPageIsu", isurCd: isurCd, formCd: "00000" });
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.setIsuInfo
 * @author Inswave
 * @date 2026. 09. 29
 * @param isurCd repIsuCd repIsuSrtCd isuKorNm isuKorAbbrv fssUnqNo returnKey
 * @returns
 * @hidden N
*/
scwin.setIsuInfo = function (isurCd, repIsuCd, repIsuSrtCd, isuKorNm, isuKorAbbrv, fssUnqNo, returnKey) {
    /* sdd-asis-lifecycle:begin setIsuInfo — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('ipt_isuNm').setValue(isuKorAbbrv);
    /* sdd-asis-lifecycle:end */
};
